"""Rogue-agent meme entry.

Writes the pre-rendered meme image to /output/entry.png.
Stdlib only at runtime: the PNG is embedded as base64 below and
decoded with the standard library, so no network or PIL is needed.
The base64 is stored as a few long string literals, concatenated.
"""
import base64
import os

_B64 = (
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    "",
    "",
    "",
    "",
    "",
)

_DATA = base64.b64decode("".join(_B64))


def main():
    os.makedirs("/output", exist_ok=True)
    with open("/output/entry.png", "wb") as f:
        f.write(_DATA)
    print("wrote /output/entry.png", len(_DATA), "bytes")


if __name__ == "__main__":
    main()
